#!/usr/bin/env python3"""Add update_base_prompts_from_xml and --update-base CLI flag to prompts.py."""import refrom pathlib import Pathtarget = Path("bin/agent/prompts.py")source = target.read_text(encoding="utf-8")# 1. Insert update_base_prompts_from_xml function before read_prompts_configfunc_code = '''def update_base_prompts_from_xml(path: str | Path | None = None) -> Path:    """Read XML system values and write them back as hardcoded defaults here."""    target = Path(path).expanduser().resolve() if path else prompts_config_path()    if not target.exists():        raise FileNotFoundError(f"prompts_config.xml not found at {target}")    tree = _read_tree(target)    root = tree.getroot()    system, _project = _ensure_sections(root)    xml_prompts = _read_prompt_section(system)    if not xml_prompts:        return target    this_file = Path(__file__).resolve()    src = this_file.read_text(encoding="utf-8")    lines: list[str] = ["DEFAULT_SYSTEM_PROMPTS: Dict[str, str] = {"]    seen: set[str] = set()    for key in DEFAULT_SYSTEM_PROMPTS:        seen.add(key)        value = xml_prompts.get(key, DEFAULT_SYSTEM_PROMPTS[key])        lines.append(f"    {key!r}: {value!r},")    for key, value in xml_prompts.items():        if key in seen:            continue        lines.append(f"    {key!r}: {value!r},")    lines.append("}")    new_block = "\\n".join(lines)    pattern = re.compile(        r"DEFAULT_SYSTEM_PROMPTS:\\s*Dict\\[str,\\s*str\\]\\s*=\\s*\\{.*?\\n\\}",        re.DOTALL,    )    if not pattern.search(src):        raise RuntimeError("Could not locate DEFAULT_SYSTEM_PROMPTS dict in prompts.py source")    updated = pattern.sub(new_block, src, count=1)    this_file.write_text(updated, encoding="utf-8")    return target'''anchor = "def read_prompts_config(path: str | Path | None = None) -> Dict[str, Dict[str, str]]:"if "def update_base_prompts_from_xml" not in source:    source = source.replace(anchor, func_code + anchor, 1)# 2. Add --update-base CLI flagif '"--update-base"' not in source:    cli_anchor = '    if "--reset-system" in args:\n        print(reset_system_prompts_to_defaults())\n        return 0'    cli_replacement = '    if "--update-base" in args:\n        print(update_base_prompts_from_xml())\n        return 0\n    if "--reset-system" in args:\n        print(reset_system_prompts_to_defaults())\n        return 0'    source = source.replace(cli_anchor, cli_replacement, 1)target.write_text(source, encoding="utf-8")print("Done: update_base_prompts_from_xml and --update-base added")